 var root=p.transform;if(!root.Find("PROJECTOR - faint authored beam")){var mesh=new Mesh{name="Cinema projection volume"};mesh.vertices=new[]{new Vector3(0,6,-28),new Vector3(-17.7f,20,-10.1f),new Vector3(17.7f,20,-10.1f)};mesh.triangles=new[]{0,1,2};mesh.uv=new[]{new Vector2(.5f,0),new Vector2(0,1),new Vector2(1,1)};mesh.colors=new[]{new Color(1,1,1,.015f),new Color(1,1,1,.008f),new Color(1,1,1,.008f)};mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,"Assets/Art/CinemaChairs/CinemaBeam.asset");var material=new Material(shader);AssetDatabase.CreateAsset(material,"Assets/Art/CinemaChairs/CinemaBeam.mat");var beam=new GameObject("PROJECTOR - faint authored beam",typeof(MeshFilter),typeof(MeshRenderer));beam.transform.SetParent(root,false);beam.GetComponent<MeshFilter>().sharedMesh=mesh;beam.GetComponent<MeshRenderer>().sharedMaterial=material;}
 foreach(var pretty in p.GetComponentsInChildren<PrettyObject>(true)){var so=new SerializedObject(pretty);so.FindProperty("useDefaultBackgroundColor").boolValue=false;so.FindProperty("backgroundColor").colorValue=new Color32(30,46,48,255);so.FindProperty("useDefaultTextColor").boolValue=false;so.FindProperty("textColor").colorValue=new Color32(248,234,205,255);so.ApplyModifiedPropertiesWithoutUndo();}EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();TheatreNativeValidation.Run();}
 public static void Boss(){if(!Application.isBatchMode)throw new Exception("Owned batch only");var scene=EditorSceneManager.OpenScene("Assets/Scenes/BossFight.unity",OpenSceneMode.Single);BossBoundControllerRepair.Run(scene);var manager=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<BossArenaManager>(true)).Single();var ms=new SerializedObject(manager);var board=(BossDefenseBoard)ms.FindProperty("_Defenses").objectReferenceValue;var allPieces=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<BossDefensePiece>(true)).ToArray();File.WriteAllText("Tools/BossFightTests/Evidence/composition/component-audit.txt","Native defense components before="+allPieces.Length+"\n");foreach(var piece in allPieces)if(piece!=board.Piece(piece.Slot))UnityEngine.Object.DestroyImmediate(piece);var rig=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<BossSegmentedRig>(true)).Single();rig.transform.position+=Vector3.up*.7f;var scale=rig.transform.localScale;scale.y*=.85f;rig.transform.localScale=scale;
